body[data-size="tiny"] .quota + .quota { margin-top: 6px; }
body[data-size="tiny"] footer { margin-top: 5px; padding-top: 4px; }
body[data-size="comfortable"] main { padding: 12px 14px; }
body[data-size="comfortable"] .quota + .quota { margin-top: 10px; }
body[data-size="comfortable"] footer { margin-top: 10px; }

