'use strict';

// A primary/secondary position alone is not evidence of a five-hour/week quota.
function normalizeWindow(raw, expectedMinutes) {
  if (!raw || raw.windowDurationMins !== expectedMinutes ||
      typeof raw.usedPercent !== 'number' || !Number.isFinite(raw.usedPercent) || raw.usedPercent < 0) {
    return null;
  }
  const remainingPercent = Math.max(0, 100 - raw.usedPercent);
  const resetsAt = Number.isSafeInteger(raw.resetsAt) && raw.resetsAt > 0
    ? raw.resetsAt * 1000 : null;
  return { usedPercent: raw.usedPercent, remainingPercent, resetsAt };
}

function normalizeUsage(response) {
  const bucket = response?.rateLimitsByLimitId?.codex ?? response?.rateLimits;
  if (!bucket || (bucket.limitId != null && bucket.limitId !== 'codex')) {
    throw Object.assign(new Error('Codex usage unavailable'), { code: 'NO_CODEX_QUOTA' });
  }
  const windows = [bucket.primary, bucket.secondary];
  return {
    fiveHour: windows.map(raw => normalizeWindow(raw, 300)).find(Boolean) ?? null,
    weekly: windows.map(raw => normalizeWindow(raw, 10080)).find(Boolean) ?? null,
    plan: typeof bucket.planType === 'string' ? bucket.planType : null,
  };
}

function publicError(error) {
  // RPC errors can contain backend URLs or account details. Do not display/log them.
  const message = typeof error?.message === 'string' ? error.message : '';
  if (/authentication required|not logged in|unauthorized|\b401\b/i.test(message)) {
    return { kind: 'auth', text: '同じ Plus アカウントでログインしてください' };
  }
  if (error?.code === 'TIMEOUT') return { kind: 'timeout', text: '取得がタイムアウトしました。再試行します' };
  if (error?.code === 'CLI_MISSING') return { kind: 'cli', text: 'Codex の実行ファイルがありません。npm ci を実行してください' };
  if (error?.code === 'NO_CODEX_QUOTA') return { kind: 'quota', text: 'Codex の利用枠が返されませんでした' };
  return { kind: 'connection', text: '使用量を取得できません。接続とログインを確認してください' };
}

function demoUsage(now = Date.now()) {
  return {
    fiveHour: { usedPercent: 28, remainingPercent: 72, resetsAt: now + 2 * 60 * 60 * 1000 },
    weekly: { usedPercent: 59, remainingPercent: 41, resetsAt: now + 3 * 24 * 60 * 60 * 1000 },
    plan: 'plus',
  };
}

module.exports = { normalizeWindow, normalizeUsage, publicError, demoUsage };

src/windows-tracker.ps1.content:
# This helper reads window bounds only. It never reads a conversation or credentials.
$ErrorActionPreference = 'Stop'
Add-Type @'
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class UsageWindows {
    public delegate bool EnumCallback(IntPtr hwnd, IntPtr context);
    [StructLayout(LayoutKind.Sequential)] public struct Rect { public int Left, Top, Right, Bottom; }
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumCallback callback, IntPtr context);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hwnd);
    [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hwnd);
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hwnd, out uint pid);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hwnd, out Rect rect);
    [DllImport("dwmapi.dll")] public static extern int DwmGetWindowAttribute(IntPtr hwnd, int attr, out Rect rect, int size);
    [DllImport("user32.dll")] public static extern bool SetProcessDpiAwarenessContext(IntPtr context);
}
'@
# Match physical DWM coordinates to Electron's explicit physical-to-DIP conversion.
[void][UsageWindows]::SetProcessDpiAwarenessContext([IntPtr](-4))
$script:chosen = [IntPtr]::Zero
$previous = ''
while ($true) {
    $script:targets = [System.Collections.Generic.List[IntPtr]]::new()
    $callback = [UsageWindows+EnumCallback] {
        param($handle, $context)
        if ([UsageWindows]::IsWindowVisible($handle)) {
            [uint32]$ownerId = 0
            [void][UsageWindows]::GetWindowThreadProcessId($handle, [ref]$ownerId)
            try {
                $owner = Get-Process -Id $ownerId -ErrorAction Stop
                if ($owner.ProcessName -match '^(ChatGPT|Codex)$') { $script:targets.Add($handle) }
            } catch { }
        }
        return $true
    }
    [void][UsageWindows]::EnumWindows($callback, [IntPtr]::Zero)
    $foreground = [UsageWindows]::GetForegroundWindow()
    [uint32]$foregroundOwner = 0
    [void][UsageWindows]::GetWindowThreadProcessId($foreground, [ref]$foregroundOwner)
    if ($script:targets.Contains($foreground)) { $script:chosen = $foreground }
    elseif (-not $script:targets.Contains($script:chosen)) {
        $script:chosen = if ($script:targets.Count -gt 0) { $script:targets[0] } else { [IntPtr]::Zero }
    }
    $payload = @{ present = $false; active = $false; minimized = $false }
    if ($script:chosen -ne [IntPtr]::Zero) {
        $rect = [UsageWindows+Rect]::new()
        $valid = [UsageWindows]::DwmGetWindowAttribute($script:chosen, 9, [ref]$rect, 16) -eq 0
        if (-not $valid) { $valid = [UsageWindows]::GetWindowRect($script:chosen, [ref]$rect) }
        if ($valid -and $rect.Right -gt $rect.Left -and $rect.Bottom -gt $rect.Top) {
            $payload = @{ present = $true; active = ($foreground -eq $script:chosen -or $foregroundOwner -eq $usageOverlayOwnerId);
                minimized = [UsageWindows]::IsIconic($script:chosen);
                x = $rect.Left; y = $rect.Top; width = $rect.Right - $rect.Left; height = $rect.Bottom - $rect.Top }
        }
    }
    $json = ConvertTo-Json -InputObject $payload -Compress
    if ($json -ne $previous) { [Console]::Out.WriteLine($json); [Console]::Out.Flush(); $previous = $json }
    Start-Sleep -Milliseconds 500
}

start.cmd.content:
@echo off
setlocal
cd /d "%~dp0"
where node >nul 2>nul
if errorlevel 1 (
  echo Node.js 22.12 or later is required. Install Node.js LTS first.
  pause
  exit /b 1
)
if not exist node_modules\electron\dist\electron.exe (
  call npm ci
  if errorlevel 1 (
    pause
    exit /b 1
  )
  call npm run install:electron
  if errorlevel 1 (
    pause
    exit /b 1
  )
)
call npm start
if errorlevel 1 pause
